0005: interface DatasetRouteContext {
0006:   readonly params: Promise<{ id: string }> | { id: string };
0007: }
0008: 
0009: async function resolveDatasetId(context: DatasetRouteContext): Promise<string> {
0010:   const params = await context.params;
0011:   const id = decodeURIComponent(params.id ?? "").trim();
0012:   if (id.length === 0) {
0013:     throw new Error("Dataset id parameter is required.");
0014:   }
0015:   return id;
0016: }
0017: 
0018: export async function GET(_request: Request, context: DatasetRouteContext): Promise<Response> {
0019:   const blocked = rejectIfProduction();
0020:   if (blocked !== null) {
0021:     return blocked;
0022:   }
0023: 
0024:   try {
0025:     const datasetId = await resolveDatasetId(context);
0026:     const payload = await loadDatasetById(datasetId);
0027: 
0028:     return NextResponse.json(payload, { status: 200 });
0029:   } catch (error) {
0030:     const message = error instanceof Error ? error.message : "Unknown dataset retrieval error.";
0031:     const status = message.includes("not registered") ? 404 : 400;
0032: 
0033:     return NextResponse.json(
0034:       {
0035:         error: message
0036:       },
0037:       {
0038:         status
0039:       }
0040:     );
0041:   }
