0001: import { createMockProvider } from "@hitech/ui-kit";
0002: import { NextResponse } from "next/server";
0003: import { rejectIfProduction } from "../../../../../../lib/dev-kpi/dev-only";
0004: import { listDatasets } from "../../../../../../lib/dev-kpi/vault";
0005: import { validateDatasetResponse } from "../../../../../../lib/dev-kpi/validation";
0006: 
0007: interface SeedRouteContext {
0008:   readonly params: Promise<{ seed: string }> | { seed: string };
0009: }
0010: 
0011: async function resolveSeed(context: SeedRouteContext): Promise<string> {
0012:   const params = await context.params;
0013:   const seed = decodeURIComponent(params.seed ?? "").trim();
0014:   if (seed.length === 0) {
0015:     throw new Error("Seed parameter is required.");
0016:   }
0017:   return seed;
0018: }
0019: 
0020: export async function GET(_request: Request, context: SeedRouteContext): Promise<Response> {
0021:   const blocked = rejectIfProduction();
0022:   if (blocked !== null) {
0023:     return blocked;
0024:   }
0025: 
0026:   try {
0027:     const seed = await resolveSeed(context);
0028:     const datasets = await listDatasets();
0029:     const provider = createMockProvider({ defaultSeed: seed });
0030: 
0031:     const generated = await Promise.all(
0032:       datasets.map(async (dataset) => {
0033:         const output = await provider.query(
0034:         {
0035:           providerId: "mock",
0036:           datasetId: dataset.datasetId,
0037:           dataShapeId: dataset.dataShapeId,
0038:           seed,
0039:           perfProfile: "default"
0040:         },
0041:         {
0042:           providerId: "mock",
0043:           stableQueryKey: `${dataset.datasetId}:${seed}`,
0044:           now: () => Date.now()
0045:         }
0046:       );
0047: 
0048:         const response = validateDatasetResponse({
0049:           datasetId: dataset.datasetId,
0050:           dataShapeId: dataset.dataShapeId,
0051:           payload: output.data,
0052:           semanticIntent: dataset.semanticIntent,
0053:           recommendedWidgets: dataset.recommendedWidgets,
0054:           tags: dataset.tags
0055:         });
0056: 
0057:         return {
0058:           ...response,
0059:           determinism: output.determinism
0060:         };
0061:       })
0062:     );
0063: 
0064:     return NextResponse.json(
0065:       {
0066:         seed,
0067:         count: generated.length,
0068:         datasets: generated
0069:       },
0070:       {
0071:         status: 200
0072:       }
0073:     );
0074:   } catch (error) {
0075:     return NextResponse.json(
0076:       {
0077:         error: error instanceof Error ? error.message : "Unknown seeded generation error."
0078:       },
0079:       {
0080:         status: 400
0081:       }
0082:     );
0083:   }
0084: }
